```c
int ident(int N, int mat[][N]) {
    int flag = 0;

    for (int i = 0; i < N; i++) {
        if (mat[i][i] == 1)
            flag = 1;

        for (int j = i + 1; j < N; j++)
            if (mat[i][j] == 0 || mat[j][i] == 0)
                flag = 1;
     }

     return flag;
}
```

```c
int ident(int N, int mat[][N]) {
    int flag = 0;

    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++)
            if (i == j && mat[i][j] == 1)
                flag = 1;
            else if (mat[i][j] == 0)
                flag = 1;
     }

     return flag;
}
```

```c
int ident(int N, int mat[][N]) {
    int flag = 1;

    for (int i = 0; i < N; i++) {
        if (mat[i][i] != 1)
            flag = 0;

        for (int j = i + 1; j < N; j++)
            if (mat[i][j] != 0 || mat[j][i] != 0)
                flag = 0;
     }

     return flag;
}
```

```c
int ident(int N, int mat[][N]) {
    int flag = 1;

    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++)
            if (i == j && mat[i][j] == 0)
                flag = 0;
            else if (i != j && mat[i][j] != 0)
                flag = 0;
            else
                flag = 1;
     }

     return flag;
}
```

